-- Check how equipment relates to locations via different paths
-- equipment -> cabinenvironment -> location
SELECT COUNT(*) FROM cabinenvironment c JOIN location l ON c.cabinlocref = l.locationregistry;

-- Check the join path: thermalsolarwindandgrid -> communication -> location
SELECT COUNT(*) FROM thermalsolarwindandgrid t 
JOIN communication c ON t.thermalcommref = c.commregistry;

-- Check: what if each thermal record maps to one equipment? 
-- And we need to join back to equipment and then to location
SELECT COUNT(*) FROM thermalsolarwindandgrid;

-- Check if all thermalsolarwindandgrid equipment codes match location equipment codes
SELECT COUNT(*) FROM thermalsolarwindandgrid t 
JOIN location l ON t.thermaleqref = l.loceqref;

